import { useState, useRef } from "react";
import "./Upload.css";

// ── Icônes SVG inline ──────────────────────────────────────────────────────────
const IconFolder = () => (
  <svg
    width="14"
    height="14"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z" />
  </svg>
);

const IconMail = () => (
  <svg
    width="44"
    height="44"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.5"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <rect width="20" height="16" x="2" y="4" rx="2" />
    <path d="m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7" />
  </svg>
);

const IconCheckCircle = () => (
  <svg
    width="44"
    height="44"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.5"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <circle cx="12" cy="12" r="10" />
    <path d="m9 12 2 2 4-4" />
  </svg>
);

const IconFile = () => (
  <svg
    width="20"
    height="20"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <path d="M15 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7Z" />
    <path d="M14 2v4a2 2 0 0 0 2 2h4" />
  </svg>
);

const IconX = () => (
  <svg
    width="16"
    height="16"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <path d="M18 6 6 18M6 6l12 12" />
  </svg>
);

const IconLightbulb = () => (
  <svg
    width="16"
    height="16"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <path d="M15 14c.2-1 .7-1.7 1.5-2.5 1-.9 1.5-2.2 1.5-3.5A6 6 0 0 0 6 8c0 1 .2 2.2 1.5 3.5.7.7 1.3 1.5 1.5 2.5" />
    <path d="M9 18h6" />
    <path d="M10 22h4" />
  </svg>
);

const IconCheck = () => (
  <svg
    width="16"
    height="16"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2.5"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <path d="M20 6 9 17l-5-5" />
  </svg>
);

const IconClock = () => (
  <svg
    width="16"
    height="16"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <circle cx="12" cy="12" r="10" />
    <path d="M12 6v6l4 2" />
  </svg>
);

const IconSquare = () => (
  <svg
    width="16"
    height="16"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <rect width="18" height="18" x="3" y="3" rx="2" />
  </svg>
);

// ──────────────────────────────────────────────────────────────────────────────

export default function Upload({ onAnalyze }) {
  const [file, setFile] = useState(null);
  const [over, setOver] = useState(false);
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState(0);
  const ref = useRef();

  const STEPS = [
    "Lecture des métadonnées…",
    "Scan des liens…",
    "Analyse du contenu…",
    "Génération du rapport…",
  ];

  const pick = (f) => {
    if (!f) return;
    if (!f.name.endsWith(".eml")) {
      alert("Veuillez sélectionner un fichier .eml");
      return;
    }
    setFile(f);
  };

  const analyze = () => {
    if (!file) return;
    setLoading(true);
    setStep(0);
    const reader = new FileReader();
    reader.onload = (e) => {
      const emlData = { content: e.target.result, name: file.name };
      let s = 0;
      const iv = setInterval(() => {
        s++;
        setStep(s);
        if (s >= STEPS.length) {
          clearInterval(iv);
          setTimeout(() => {
            setLoading(false);
            onAnalyze(emlData);
          }, 400);
        }
      }, 800);
    };
    reader.readAsText(file);
  };

  const stepIcon = (i) => {
    if (i < step) return <IconCheck />;
    if (i === step) return <IconClock />;
    return <IconSquare />;
  };

  return (
    <div className="upload-page">
      {/* Header */}
      <div className="upload-header">
        <div className="upload-badge">
          <IconFolder /> Étape 1 sur 2
        </div>
        <h1>
          Importez votre <span>Email</span>
        </h1>
        <p>
          Chargez votre fichier .eml et laissez notre plateforme analyser les
          menaces de sécurité en quelques secondes.
        </p>
      </div>

      {/* Card */}
      <div className="upload-card">
        {/* Drop zone */}
        <div
          className={`drop-zone ${over ? "over" : ""} ${file ? "done" : ""}`}
          onClick={() => ref.current.click()}
          onDragOver={(e) => {
            e.preventDefault();
            setOver(true);
          }}
          onDragLeave={() => setOver(false)}
          onDrop={(e) => {
            e.preventDefault();
            setOver(false);
            pick(e.dataTransfer.files[0]);
          }}
        >
          <input
            ref={ref}
            type="file"
            accept=".eml"
            style={{ display: "none" }}
            onChange={(e) => pick(e.target.files[0])}
          />
          <span className="drop-icon">
            {file ? <IconCheckCircle /> : <IconMail />}
          </span>
          <h3>
            {file
              ? "Fichier sélectionné !"
              : "Glissez-déposez votre fichier ici"}
          </h3>
          <p>
            ou <strong>cliquez pour sélectionner</strong> un fichier depuis
            votre ordinateur
          </p>
        </div>

        {/* Aperçu fichier */}
        {file && (
          <div className="file-preview">
            <div className="file-icon-box">
              <IconFile />
            </div>
            <div className="file-info">
              <div className="file-name">{file.name}</div>
              <div className="file-size">
                {(file.size / 1024).toFixed(1)} KB
              </div>
            </div>
            <button
              className="file-remove"
              onClick={(e) => {
                e.stopPropagation();
                setFile(null);
              }}
            >
              <IconX />
            </button>
          </div>
        )}

        {/* Hint */}
        <div className="upload-hint">
          <span>
            <IconLightbulb />
          </span>
          <p>
            Pour exporter au format <strong>.eml</strong> depuis Outlook : clic
            droit → "Enregistrer sous". Depuis Gmail : menu "Plus" →
            "Télécharger le message".
          </p>
        </div>

        {/* Bouton */}
        <button className="analyze-btn" disabled={!file} onClick={analyze}>
          Analyser cet email
        </button>
      </div>

      {/* Loading overlay */}
      {loading && (
        <div className="loading-overlay">
          <div className="loading-card">
            <div className="spinner" />
            <h3>Analyse en cours…</h3>
            <p>Notre plateforme examine votre email en profondeur.</p>
            <div className="loading-steps">
              {STEPS.map((s, i) => (
                <div
                  key={i}
                  className={`load-step ${
                    i < step ? "done" : i === step ? "active" : ""
                  }`}
                >
                  {stepIcon(i)} {s}
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
